require_once __DIR__.'/config.php'; require_login();if(!fams_current_type_allows('MAIFIP','view_records')){http_response_code(403);exit('Your user type does not have permission for this action. Contact the Site Administrator if this access is required.');}
$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$activeFacility=active_data_facility($pdo);$perPage=25;$page=max(1,(int)($_GET['page']??1)); $sql='SELECT * FROM assistance_records WHERE facility=?';$params=[$activeFacility];
if($q!==''){ $sql.=' AND (control_number LIKE ? OR patient_first_name LIKE ? OR patient_middle_name LIKE ? OR patient_last_name LIKE ? OR barangay LIKE ? OR municipality LIKE ? OR guardian LIKE ? OR
        contact_number LIKE ? OR remarks LIKE ?)';$n="%{$q}%";for($i=0;$i<9;$i++)$params[]=$n; }
if($status!==''){ $sql.=' AND status=?';$params[]=$status; } $countSql=preg_replace('/^SELECT \* FROM assistance_records/','SELECT COUNT(*) FROM assistance_records',$sql);$cs=$pdo->prepare($countSql);$cs->execute($params);$total=(int)$cs->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$sql.=' ORDER BY date_submission DESC,id DESC LIMIT '.$perPage.' OFFSET '.$offset;$st=$pdo->prepare($sql);$st->execute($params);$records=$st->fetchAll();
$user=current_user();
header('Content-Type: application/json; charset=utf-8');
