$canChangeThisStatus=can_update_status();
$beneficiaryName=trim(($row['patient_first_name']??'').' '.($row['patient_middle_name']??'').' '.($row['patient_last_name']??'').' '.($row['patient_name_extension']??''));
?>
<tr>
<td><strong><?=e(date('M d, Y',strtotime($row['date_submission'])))?></strong><br><small><?=e($row['control_number'])?></small></td>
<td><strong><?=e($beneficiaryName?:'—')?></strong></td>
<td><strong><?=e($row['guardian']?:'—')?></strong><?php if(!empty($row['contact_number'])):?><br><small><?=e($row['contact_number'])?></small><?php endif;?></td>
<td><strong><?=e($row['barangay']?:'—')?></strong><br><small><?=e(trim(($row['municipality']??'').(!empty($row['province'])?', '.$row['province']:''))?:'—')?></small></td>
<td class="fams-amount-cell"><strong>₱<?=number_format((float)($row['bill_amount']??0),2)?></strong></td>
<td class="fams-amount-cell"><strong>₱<?=number_format((float)($row['guarantee_amount']??0),2)?></strong></td>
<td><strong><?=e($row['remarks']?:'—')?></strong></td>
<td><?php if($canChangeThisStatus):?><form method="post" action="status_update.php" class="inline-status-form" data-status-form data-record-status="<?=e(strtoupper((string)$row['status']))?>" data-record-id="<?=(int)$row['id']?>" data-user-role="<?=e($user['role']??'')?>" data-submission-date="<?=e($row['date_submission'])?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><select name="status" class="status-select <?=e(status_class($row['status']))?>" data-status-select aria-label="Change status for <?=e($row['control_number'])?>"><?php foreach(['WAITING','RELEASED','CANCELLED'] as $st):?><option value="<?=e($st)?>" <?=$row['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><div class="status-popover" data-status-popover hidden><div class="status-popover-title">Update <?=e($row['control_number'])?></div><label>Release Date <span class="field-required" data-release-required>*</span></label><input type="date" name="release_date" value="<?=e((string)$row['release_date'])?>" max="<?=e(date('Y-m-d'))?>" data-release-date><small class="date-rule">Must be later than <?=e(date('M d, Y',strtotime($row['date_submission'])))?> and not later than today.</small><label>Remarks <span class="field-required" data-remarks-required hidden>*</span></label><textarea name="remarks" rows="3" data-status-remarks><?=e((string)$row['remarks'])?></textarea><div class="status-popover-help" data-status-help></div><div class="status-popover-actions"><button type="button" class="ghost-btn status-cancel" data-status-cancel>Cancel</button><button type="submit" class="primary-btn">Save</button></div></div></form><?php else:?><span class="status-badge <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span><?php endif;?></td>
