lete_request.php?id=<?=(int)$row['id']?>&popup=1" aria-label="Request delete entry approval" title="Request delete entry approval"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13"/></svg></a><?php endif;?></div></td><?php endif;?>
</tr>
<?php endforeach; if(!$records): ?><tr><td colspan="<?= (($user['role']??'')==='social_worker')?8:9 ?>" class="empty-cell">No records found.</td></tr><?php endif; $html=ob_get_clean(); $paginationParams=['q'=>$q,'status'=>$status];$paginationParams=array_filter($paginationParams,static fn($v)=>$v!=='');ob_start(); ?><div class="fams-pagination-summary">Showing <?=number_format($total?$offset+1:0)?>–<?=number_format(min($offset+$perPage,$total))?> of <?=number_format($total)?> records</div><div class="fams-pagination-controls"><?php if($page>1): ?><a href="records.php?<?=e(http_build_query($paginationParams+['page'=>1]))?>" data-masterlist-page="1">« First</a><a href="records.php?<?=e(http_build_query($paginationParams+['page'=>$page-1]))?>" data-masterlist-page="<?=$page-1?>">‹ Previous</a><?php endif; ?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages): ?><a href="records.php?<?=e(http_build_query($paginationParams+['page'=>$page+1]))?>" data-masterlist-page="<?=$page+1?>">Next ›</a><a href="records.php?<?=e(http_build_query($paginationParams+['page'=>$pages]))?>" data-masterlist-page="<?=$pages?>">Last »</a><?php endif; ?></div><?php $pagination=ob_get_clean(); echo json_encode(['html'=>$html,'count'=>$total,'pagination'=>$pagination,'page'=>$page,'pages'=>$pages]);
